/**
 * /api/radio/lexicon — 电台词典的教学与查询。
 *
 * GET            列出内置 + 已学会的词（ learned 标注来源）。
 * POST {term, kind, tags}  教一个新词：{"term":"丧","kind":"mood","tags":["melancholic","sad"]}。
 *                          写入 data/lexicon-learned.json，立即生效——词汇层的长期记忆。
 *
 * 回路：parseQuery 遇到生词 → unknownTerms 返回给 agent → agent 追问/推断 →
 * 调本接口教学 → 下次点播该词直接命中。LLM 在线的唯一职责是这条教学链路。
 */
import { GENRE_LEXICON, MOOD_LEXICON, lookupTerm, teachTerm } from '@/server/radio/lexicon';
import { ok, fail } from '@/server/http';

export async function GET() {
	const learned: Record<string, unknown> = {};
	try {
		// learned 优先展示（覆盖内置的也标出来）
		const { existsSync, readFileSync } = await import('node:fs');
		const p = `${process.cwd()}/data/lexicon-learned.json`;
		if (existsSync(p)) {
			const parsed = JSON.parse(readFileSync(p, 'utf8')) as Record<string, unknown>;
			Object.assign(learned, parsed);
		}
	} catch {
		/* 损坏文件当没有 */
	}
	return ok({
			builtinMoods: Object.keys(MOOD_LEXICON),
			builtinGenres: Object.keys(GENRE_LEXICON),
			learned,
		});
}

export async function POST(request: Request) {
	let body: { term?: unknown; kind?: unknown; tags?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}
	const term = typeof body.term === 'string' ? body.term.trim() : '';
	const kind = body.kind === 'genre' ? 'genre' : 'mood';
	const tags = Array.isArray(body.tags) ? body.tags.filter((t): t is string => typeof t === 'string') : [];
	if (!term || tags.length === 0) {
		return fail('term and tags are required', 400);
	}
	teachTerm(term, kind, tags);
	return ok({ term, kind, tags, resolved: lookupTerm(term) });
}
